// @ts-check
/**
 * Pure helpers of scripts/release/third-party-notices.mjs: import scanning, package metadata and the
 * generated LICENSE.md text. Nothing here touches the file system, so the rules can be unit tested.
 */
import { compareCodeUnits } from "./files.mjs";
import { isRecord } from "./json.mjs";

/** First line of every generated file; also how the script recognises files it may rewrite or delete. */
export const GENERATED_MARKER =
  "<!-- Generated by scripts/release/third-party-notices.mjs when the package is packed for release. Do not edit or commit. -->";

/** Import queries that inline a file into the output (Vite-style `?raw`, `?inline`, `?url`). */
const ASSET_QUERY = /\?(?:raw|inline|url)$/;

/**
 * @typedef {object} ImportedPackage
 * @property {string} name npm package name
 * @property {boolean} asset true when at least one import inlines a file of the package (`?raw`, `?inline`, `?url`)
 */

/**
 * Lists the npm packages a JavaScript, TypeScript, HTML or CSS source imports at run time: static and
 * dynamic imports, re-exports, side-effect imports and CSS `@import`. `import type` and `export type`
 * are skipped; relative, absolute, `node:` and virtual specifiers are ignored. Matching is textual, so
 * an import written in a comment counts too: the result may list more packages, never fewer.
 * @param {string} source
 * @returns {ImportedPackage[]} sorted by name
 */
export function runtimeImports(source) {
  /** @type {Map<string, boolean>} */
  const found = new Map();
  /** @param {string} specifier */
  const add = (specifier) => {
    const name = packageNameOf(specifier);
    if (name) found.set(name, (found.get(name) ?? false) || ASSET_QUERY.test(specifier));
  };
  const statement = /\b(?:import|export)\s+(type\s+)?(?:[^;'"`]*?\bfrom\s*)?["']([^"'\n]+)["']/g;
  for (const match of source.matchAll(statement)) if (!match[1]) add(match[2] ?? "");
  for (const match of source.matchAll(/\bimport\s*\(\s*["']([^"'\n]+)["']\s*\)/g)) add(match[1] ?? "");
  for (const match of source.matchAll(/@import\s+(?:url\(\s*)?["']([^"'\n]+)["']/g)) add(match[1] ?? "");
  return [...found].map(([name, asset]) => ({ name, asset })).sort((a, b) => compareCodeUnits(a.name, b.name));
}

/**
 * The npm package a bare import specifier points into (`katex/dist/x.css?raw` -> `katex`).
 * @param {string} specifier
 * @returns {string | null} null for relative, absolute, URL, `node:` and virtual specifiers
 */
export function packageNameOf(specifier) {
  const bare = specifier.split("?")[0] ?? "";
  if (!bare || /^[./\\#~]|^[a-z][\w+.-]*:/i.test(bare) || bare.startsWith("\0")) return null;
  const parts = bare.split("/");
  const name = bare.startsWith("@") ? parts.slice(0, 2).join("/") : (parts[0] ?? "");
  return /^(?:@[a-z0-9][\w.-]*\/)?[a-z0-9][\w.-]*$/i.test(name) ? name : null;
}

/**
 * Packages a built file was bundled from, read from the module paths bundlers leave behind: esbuild's
 * `// node_modules/...` comments in unminified output and the `sources` of source maps.
 * @param {string} text contents of a .js, .mjs, .css or .map file
 * @returns {string[]} sorted package names
 */
export function bundledPackagesInOutput(text) {
  const names = new Set();
  const path = /node_modules\/(?:\.pnpm\/[^/"'\s]+\/node_modules\/)?((?:@[\w.-]+\/)?[\w.-]+)\//g;
  for (const match of text.matchAll(path)) if (match[1] && !match[1].startsWith(".")) names.add(match[1]);
  return [...names].sort(compareCodeUnits);
}

/**
 * The SPDX expression of a manifest's `license` field (or the legacy `{ type }` object).
 * @param {Record<string, unknown>} manifest
 */
export function licenseOf(manifest) {
  const { license } = manifest;
  if (typeof license === "string") return license;
  if (isRecord(license) && typeof license.type === "string") return license.type;
  return "UNKNOWN";
}

/**
 * A browsable source URL from a manifest's `repository` (string shorthand or `{ url }` object).
 * @param {Record<string, unknown>} manifest
 * @returns {string | null}
 */
export function repositoryUrl(manifest) {
  const repository = manifest.repository;
  const raw = typeof repository === "string" ? repository : isRecord(repository) ? repository.url : undefined;
  if (typeof raw !== "string" || !raw) return typeof manifest.homepage === "string" ? manifest.homepage : null;
  const shorthand = /^(?:github:)?([\w.-]+\/[\w.-]+)$/.exec(raw);
  if (shorthand) return `https://github.com/${shorthand[1]}`;
  return raw
    .replace(/^git\+/, "")
    .replace(/^git:\/\//, "https://")
    .replace(/^ssh:\/\/git@/, "https://")
    .replace(/^git@([^:]+):/, "https://$1/")
    .replace(/\.git$/, "");
}

/**
 * Splits a package's top-level file names into licence and notice files.
 * @param {readonly string[]} names
 */
export function legalFiles(names) {
  const sorted = [...names].sort(compareCodeUnits);
  return {
    licenses: sorted.filter((name) => /^(?:licen[cs]e|copying)(?:[.-][\w.-]*)?$/i.test(name)),
    notices: sorted.filter((name) => /^notice(?:\.[\w]+)?$/i.test(name)),
  };
}

/**
 * The licence section of a README, for small packages that put their licence text there instead of in a
 * LICENSE file: from a `License` / `Licence` heading to the next heading of the same or a higher level.
 * @param {string} markdown
 * @returns {string | null} null when there is no such section or it holds no copyright line
 */
export function readmeLicenseSection(markdown) {
  const lines = markdown.replace(/\r\n/g, "\n").split("\n");
  const start = lines.findIndex((line) => /^#{1,6}\s+licen[cs]e\b/i.test(line));
  if (start < 0) return null;
  const level = /^#+/.exec(lines[start] ?? "")?.[0].length ?? 1;
  let end = start + 1;
  while (end < lines.length && !new RegExp(`^#{1,${level}}\\s`).test(lines[end] ?? "")) end++;
  const section = lines
    .slice(start + 1, end)
    .join("\n")
    .trim();
  return /copyright/i.test(section) ? section : null;
}

/**
 * The copyright lines of a source file's leading comment (`Copyright ...`, `(c) ...` or `© ...`, each up to
 * the end of the line or a `|` / `*`), for packages that state their copyright there and not in their
 * licence file. Bundlers drop the comment, so the generated notices repeat the lines.
 * @param {string} source
 * @returns {string | null} the lines joined by newlines, null when the comment holds none
 */
export function headerCopyright(source) {
  const comment = /^\s*\/\*[\s\S]*?\*\//.exec(source)?.[0] ?? "";
  const lines = [...comment.matchAll(/(?:\bCopyright\b|\(c\)|©)[^\n|*]*/g)].map((match) => match[0].trim());
  return lines.length > 0 ? [...new Set(lines)].join("\n") : null;
}

/**
 * Whether a licence text holds a copyright line of its own (the MPL-2.0 and Apache-2.0 texts hold none).
 * @param {string} text
 */
export function hasCopyrightLine(text) {
  return /^\W*(?:Copyright\b(?! \[yyyy\])|\(c\)\s*\d|©)/m.test(text);
}

const MIT_TERMS = `Permission is hereby granted, free of charge, to any person obtaining a copy of this software and
associated documentation files (the "Software"), to deal in the Software without restriction, including
without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the
following conditions:

The above copyright notice and this permission notice shall be included in all copies or substantial
portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT
LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO
EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER
IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR
THE USE OR OTHER DEALINGS IN THE SOFTWARE.`;

/**
 * The MIT licence text for a package that declares `"license": "MIT"` but ships no licence file (common
 * in the unified ecosystem, whose READMEs end with `[MIT][license] © [Author][author]`). The copyright
 * holder comes from that README line, else from the manifest's `author`.
 * @param {Record<string, unknown>} manifest
 * @param {string} readme
 * @returns {string | null} null when the package is not MIT or names no copyright holder
 */
export function synthesizedMitLicense(manifest, readme) {
  if (licenseOf(manifest) !== "MIT") return null;
  const line = /\bMIT\b[^\n]*?©\s*([^\n]+)/.exec(readme)?.[1];
  const fromReadme = line
    ?.replace(/\[([^\]]*)\]\[[^\]]*\]/g, "$1")
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
    .trim();
  const author = manifest.author;
  const fromManifest = typeof author === "string" ? author : isRecord(author) ? author.name : undefined;
  const holder = fromReadme || (typeof fromManifest === "string" ? fromManifest.trim() : "");
  if (!holder) return null;
  return mitLicense(
    holder,
    "The npm package ships no licence file; this is the MIT text with the copyright line from its README or package.json.",
  );
}

/**
 * The MIT licence text for a copyright holder, with a note on where the copyright line comes from.
 * @param {string} holder
 * @param {string} note
 */
export function mitLicense(holder, note) {
  return `MIT License\n\nCopyright (c) ${holder}\n\n${MIT_TERMS}\n\n(${note})`;
}

/**
 * @typedef {object} NoticeEntry
 * @property {string} name
 * @property {string} license SPDX expression from the manifest
 * @property {string | null} source browsable source location
 * @property {string} text licence text, then NOTICE text when the package ships one
 */

/** @param {string} text */
function fenced(text) {
  let fence = "```";
  while (text.includes(fence)) fence += "`";
  return `${fence}text\n${text.trim()}\n${fence}`;
}

/**
 * Renders a package's LICENSE.md: the package's own licence, then every bundled third-party package
 * with its licence text. Packages with identical texts share one copy of it. Without entries the file
 * holds the package's own licence only.
 * @param {string} packageName
 * @param {string} ownLicense the repository LICENSE text
 * @param {readonly NoticeEntry[]} entries
 */
export function renderLicenseFile(packageName, ownLicense, entries) {
  if (entries.length === 0) return [GENERATED_MARKER, "", ownLicense.trim(), ""].join("\n");
  /** @type {Map<string, NoticeEntry[]>} */
  const byText = new Map();
  for (const entry of [...entries].sort((a, b) => compareCodeUnits(a.name, b.name))) {
    const key = entry.text.trim().replace(/\r\n/g, "\n");
    byText.set(key, [...(byText.get(key) ?? []), entry]);
  }
  const sections = [...byText].map(([text, group]) => {
    const lines = group.map(({ name, license, source }) => `- \`${name}\`: ${license}${source ? `, ${source}` : ""}`);
    return `## ${group.map((entry) => entry.name).join(", ")}\n\n${lines.join("\n")}\n\n${fenced(text)}`;
  });
  return [
    GENERATED_MARKER,
    "",
    ownLicense.trim(),
    "",
    "---",
    "",
    "# Third-party software",
    "",
    `\`${packageName}\` bundles code or assets from the open source packages below. Their licences apply to ` +
      "those parts; each licence text is reproduced in full, followed by the package's NOTICE where it has one.",
    "",
    sections.join("\n\n"),
    "",
  ].join("\n");
}
